mapper.select:
 SELECT h.*,c.name customer_name,ct.name customer_type_name,s.sku_code,s.spec_name,sp.name product_name FROM (
SELECT l.id history_id,'AGREEMENT' source,l.agreement_price_id price_id,p.customer_id,NULL::bigint customer_type_id,p.sku_id,l.operation_type,l.operator,l.created_at operated_at,l.before_data,l.after_data,p.unit_price current_unit_price,p.effective_from current_effective_from,p.effective_to current_effective_to,COALESCE(p.deleted,TRUE) current_deleted FROM customer_agreement_price_operation_log l LEFT JOIN customer_agreement_price p ON p.id=l.agreement_price_id UNION ALL SELECT l.id history_id,'CUSTOMER_TYPE' source,l.customer_type_price_id price_id,NULL::bigint customer_id,p.customer_type_id,p.sku_id,l.operation_type,l.operator,l.created_at operated_at,l.before_data,l.after_data,p.unit_price current_unit_price,p.effective_from current_effective_from,p.effective_to current_effective_to,COALESCE(p.deleted,TRUE) current_deleted FROM customer_type_price_operation_log l LEFT JOIN customer_type_price p ON p.id=l.customer_type_price_id) h LEFT JOIN customer c ON c.id=h.customer_id LEFT JOIN customer_type ct ON ct.id=h.customer_type_id LEFT JOIN product_sku s ON s.id=h.sku_id LEFT JOIN product_spu sp ON sp.id=s.spu_id  AND h.source=#{query.source}
 AND h.customer_id=#{query.customerId}
 AND h.customer_type_id=#{query.customerTypeId}
 AND h.sku_id=#{query.skuId}
 AND h.operation_type=#{query.operationType}
 AND h.operated_at >= #{query.operatedFrom}
 AND h.operated_at <= #{query.operatedTo}
 AND COALESCE(h.current_effective_to,'infinity'::timestamptz) > #{query.effectiveFrom}
 AND h.current_effective_from < #{query.effectiveTo}
 ORDER BY h.operated_at DESC,h.history_id DESC,h.source
